1	package testutil
2	
3	import (
4		"fmt"
5		"image/color"
6		"strings"
7		"unicode/utf8"
8	
9		"github.com/charmbracelet/x/ansi"
10	)
11	
12	// Cell decoding (DEVDESK-281). A rendered frame is a string of text and SGR
13	// sequences; two frames can differ byte for byte (a redundant reset, a colour
14	// written as 24-bit or as the same palette entry) and still paint the same
15	// screen. A test that guards a change to how a frame is built therefore
16	// compares cells: what the terminal would show at each position.
17	//
18	// The decoder walks the frame with x/ansi's sequence decoder (the same
19	// grapheme clustering and widths Lip Gloss and the viewport measure with) and
20	// follows the SGR state. It tracks the foreground, the background and reverse
21	// video, nothing else: bold, underline and the like do not change which colour
22	// a cell has, which is what the Rule 115 check and the golden compare. Every
23	// sequence that is not an SGR (cursor moves, erases, OSC titles, hyperlinks,
24	// progress) is skipped and paints nothing.
25	
26	// DefaultColor is the colour of a cell no sequence has coloured: the
27	// terminal's own foreground or background.
28	const DefaultColor = ""
29	
30	// Colour names a Cell carries. A colour is DefaultColor, "#rrggbb" for a 24-bit
31	// one, "ansi:N" for palette entries 0 to 15 (SGR 30-37, 90-97, 40-47, 100-107
32	// and 38;5;N or 48;5;N with N below 16, which a terminal draws the same) and
33	// "idx:N" for entries 16 to 255. Under reverse video the two colours swap; a
34	// default one that lands on the other side is not the terminal's background
35	// (nor foreground) any more, so it is named for what it now is:
36	const (
37		// ReversedDefaultFG is the background of a reversed cell whose foreground was
38		// the terminal's default: the terminal's default foreground, as a fill.
39		ReversedDefaultFG = "default-fg"
40		// ReversedDefaultBG is the foreground of a reversed cell whose background was
41		// the terminal's default.
42		ReversedDefaultBG = "default-bg"
43	)
44	
45	// Cell is one terminal cell: the grapheme drawn there and its colours.
46	// A grapheme wider than one cell occupies several: the first holds the glyph,
47	// the following ones have an empty Glyph and the same colours.
48	type Cell struct {
49		Glyph  string
50		FG, BG string
51	}
52	
53	// Pos is a cell's position in a frame, zero-based.
54	type Pos struct{ Row, Col int }
55	
56	// Cells decodes a frame into one row of cells per line. A frame without a
57	// newline is one row; an empty frame is one empty row. The rows are as long as
58	// what was written: a row shorter than the screen is not padded.
59	func Cells(frame string) [][]Cell {
60		rows := [][]Cell{nil}
61		var st sgrState
62		p := ansi.NewParser()
63		var state byte
64		for rest := frame; len(rest) > 0; {
65			var seq string
66			var width, n int
67			seq, width, n, state = ansi.DecodeSequence(rest, state, p)
68			rest = rest[n:]
69			switch {
70			case seq == "\n":
71				rows = append(rows, nil)
72			case width > 0:
73				fg, bg := st.colours()
74				last := len(rows) - 1
75				rows[last] = append(rows[last], Cell{Glyph: seq, FG: fg, BG: bg})
76				for i := 1; i < width; i++ {
77					rows[last] = append(rows[last], Cell{FG: fg, BG: bg})
78				}
79			case width == 0 && isZeroWidthText(seq):
80				// A combining mark or joiner the decoder did not cluster with the
81				// ASCII letter before it: it belongs to that cell.
82				attach(rows[len(rows)-1], seq)
83			case isSGR(seq, p):
84				st.apply(p.Params())
85			}
86		}
87		return rows
88	}
89	
90	// isZeroWidthText reports whether seq is zero-width printable text (a combining
91	// mark, a joiner, a variation selector), as opposed to a control or an escape
92	// sequence.
93	func isZeroWidthText(seq string) bool {
94		r, _ := utf8.DecodeRuneInString(seq)
95		return r >= 0xA0 && r != utf8.RuneError
96	}
97	
98	// attach appends seq to the glyph of the last glyph-bearing cell of row. In an
99	// empty row it is dropped: there is nothing to combine with.
100	func attach(row []Cell, seq string) {
101		for i := len(row) - 1; i >= 0; i-- {
102			if row[i].Glyph != "" {
103				row[i].Glyph += seq
104				return
105			}
106		}
107	}
108	
109	// BareCells returns the position of every cell whose background is the
110	// terminal's default, in reading order. A frame that sets its own background
111	// everywhere returns none (Rule 115). A cell the frame never wrote, because a
112	// row is shorter than the screen, is not in the frame and so not in the result:
113	// the caller checks the row lengths against the width it expects.
114	func BareCells(frame string) []Pos {
115		var out []Pos
116		for r, row := range Cells(frame) {
117			for c, cell := range row {
118				if cell.BG == DefaultColor {
119					out = append(out, Pos{Row: r, Col: c})
120				}
121			}
122		}
123		return out
124	}
125	
126	// isSGR reports whether seq, just decoded into p, is a plain CSI ... m.
127	func isSGR(seq string, p *ansi.Parser) bool {
128		if !strings.HasPrefix(seq, "\x1b[") {
129			return false
130		}
131		cmd := ansi.Cmd(p.Command())
132		return cmd.Final() == 'm' && cmd.Prefix() == 0 && cmd.Intermediate() == 0
133	}
134	
135	// sgrState is the colour part of the graphic rendition.
136	type sgrState struct {
137		fg, bg  string
138		reverse bool
139	}
140	
141	// colours returns the colours a cell drawn now has.
142	func (s *sgrState) colours() (fg, bg string) {
143		if !s.reverse {
144			return s.fg, s.bg
145		}
146		fg, bg = s.bg, s.fg
147		if fg == DefaultColor {
148			fg = ReversedDefaultBG
149		}
150		if bg == DefaultColor {
151			bg = ReversedDefaultFG
152		}
153		return fg, bg
154	}
155	
156	// apply follows one SGR sequence. An unreadable colour ends the sequence, as a
157	// terminal would not know where the next attribute starts.
158	func (s *sgrState) apply(params ansi.Params) {
159		if len(params) == 0 {
160			*s = sgrState{}
161			return
162		}
163		for i := 0; i < len(params); {
164			v := params[i].Param(0)
165			if params[i].HasMore() && v != 38 && v != 48 {
166				// A sub-parameter chain such as 4:3 (curly underline): none of it is
167				// a colour attribute, and a 0 inside it must not reset anything.
168				for i < len(params) && params[i].HasMore() {
169					i++
170				}
171				i++
172				continue
173			}
174			switch {
175			case v == 0:
176				*s = sgrState{}
177			case v == 7:
178				s.reverse = true
179			case v == 27:
180				s.reverse = false
181			case v >= 30 && v <= 37:
182				s.fg = paletteName(v - 30)
183			case v == 39:
184				s.fg = DefaultColor
185			case v >= 40 && v <= 47:
186				s.bg = paletteName(v - 40)
187			case v == 49:
188				s.bg = DefaultColor
189			case v >= 90 && v <= 97:
190				s.fg = paletteName(v - 90 + 8)
191			case v >= 100 && v <= 107:
192				s.bg = paletteName(v - 100 + 8)
193			case v == 38 || v == 48:
194				var c color.Color
195				n := ansi.ReadStyleColor(params[i:], &c)
196				if n == 0 {
197					return
198				}
199				if v == 38 {
200					s.fg = colourName(c)
201				} else {
202					s.bg = colourName(c)
203				}
204				i += n
205				continue
206			}
207			i++
208		}
209	}
210	
211	// paletteName names palette entry n (0 to 255).
212	func paletteName(n int) string {
213		if n < 16 {
214			return fmt.Sprintf("ansi:%d", n)
215		}
216		return fmt.Sprintf("idx:%d", n)
217	}
218	
219	// colourName names a decoded colour.
220	func colourName(c color.Color) string {
221		switch c := c.(type) {
222		case ansi.IndexedColor:
223			return paletteName(int(c))
224		case ansi.BasicColor:
225			return paletteName(int(c))
226		}
227		r, g, b, _ := c.RGBA()
228		return fmt.Sprintf("#%02x%02x%02x", r>>8, g>>8, b>>8)
229	}
230	
231	// FormatCells renders decoded cells as a stable, readable text, for a golden
232	// file: a legend of the distinct styles (a foreground and a background, named
233	// in order of first appearance), then per row a glyph line and a style line.
234	// Both lines sit between bars so a trailing space can be seen. The style line
235	// has one character per cell; the glyph line has one glyph per grapheme, so a
236	// wide glyph is one character there and two in the style line.
237	//
238	//	styles
239	//	  0: fg=- bg=#1e1e2e
240	//	  1: fg=#cdd6f4 bg=#1e1e2e
241	//	rows 2
242	//	00 |ab |
243	//	   |011|
244	func FormatCells(rows [][]Cell) string {
245		type style struct{ fg, bg string }
246		ids := map[style]rune{}
247		var order []style
248		idOf := func(c Cell) rune {
249			k := style{c.FG, c.BG}
250			id, ok := ids[k]
251			if !ok {
252				id = styleRune(len(order))
253				ids[k] = id
254				order = append(order, k)
255			}
256			return id
257		}
258	
259		var body strings.Builder
260		fmt.Fprintf(&body, "rows %d\n", len(rows))
261		for r, row := range rows {
262			var glyphs, styles strings.Builder
263			for _, c := range row {
264				glyphs.WriteString(c.Glyph)
265				styles.WriteRune(idOf(c))
266			}
267			fmt.Fprintf(&body, "%02d |%s|\n   |%s|\n", r, glyphs.String(), styles.String())
268		}
269	
270		var out strings.Builder
271		out.WriteString("styles\n")
272		dash := func(s string) string {
273			if s == DefaultColor {
274				return "-"
275			}
276			return s
277		}
278		for i, k := range order {
279			fmt.Fprintf(&out, "  %c: fg=%s bg=%s\n", styleRune(i), dash(k.fg), dash(k.bg))
280		}
281		out.WriteString(body.String())
282		return out.String()
283	}
284	
285	// styleRune is the one-cell-wide character naming the i-th style: digits and
286	// letters first, then the Latin-1 and Latin Extended-A letters, all single
287	// width.
288	func styleRune(i int) rune {
289		const alnum = "REDACTED"
290		if i < len(alnum) {
291			return rune(alnum[i])
292		}
293		return rune(0x100 + i - len(alnum))
294	}
