1	package testutil
2	
3	import (
4		"reflect"
5		"strings"
6		"testing"
7	
8		"github.com/charmbracelet/x/ansi"
9	)
10	
11	// The cell decoder is the safety net under any change to how a frame is
12	// rendered (DEVDESK-281): two frames are the same when their cells are, not
13	// when their bytes are. These tests pin what a cell is, so a golden built on
14	// it does not drift with the decoder.
15	
16	// glyphs returns the glyph of each cell of a row.
17	func glyphs(row []Cell) []string {
18		out := make([]string, len(row))
19		for i, c := range row {
20			out[i] = c.Glyph
21		}
22		return out
23	}
24	
25	func TestCellsPlainText(t *testing.T) {
26		rows := Cells("ab\ncd")
27		want := [][]Cell{
28			{{"a", "", ""}, {"b", "", ""}},
29			{{"c", "", ""}, {"d", "", ""}},
30		}
31		if !reflect.DeepEqual(rows, want) {
32			t.Fatalf("Cells = %#v, want %#v", rows, want)
33		}
34	}
35	
36	func TestCellsColours(t *testing.T) {
37		tests := []struct {
38			name           string
39			in             string
40			wantFG, wantBG string
41		}{
42			{"24-bit foreground and background", "\x1b[38;2;1;2;3m\x1b[48;2;255;16;0mx", "#010203", "#ff1000"},
