19	// The frame, compared by cells (DEVDESK-281, task 281.2).
20	//
21	// The router assembles the frame in a few passes (renderBody's Style.Width,
22	// fitHeight, the whole-frame lipgloss.Place, the palette overlay). Changing how
23	// one of them pads changes bytes without necessarily changing what a terminal
24	// shows, so the safety net is not a byte comparison: testutil.Cells decodes the
25	// frame into (glyph, foreground, background) per cell, and
26	//
27	//   - TestFrameHasNoBareCell holds Rule 115: no cell of the frame is left on the
28	//     terminal's default background, and the frame is exactly width x height;
29	//   - TestFrameCellsGolden compares the whole decoded frame, case by case,
30	//     against internal/app/testdata/frames/<case>.cells.
31	//
32	// Both run at 120x40 with the TrueColor profile, on the default theme.
33	//
34	// Regenerate the goldens after an intended rendering change, then read the diff
35	// as cells:
36	//
37	//	go test ./internal/app -run TestFrameCellsGolden -update-frames -count=1
38	//
39	// The flag is the package's own: pass it with the package path, not ./...
40	
41	var updateFrames = flag.Bool("update-frames", false, "rewrite internal/app/testdata/frames/*.cells from the current frames")
42	
43	const (
44		framesWidth  = 120
45		framesHeight = 40
46		framesDir    = "testdata/frames"
47	)
