49	// cellsView is a footedView whose footer carries its own background: footedView's
50	// writes "FOOTER" with none, and this net would rightly call those cells bare.
51	type cellsView struct{ footedView }
52	
53	func (v *cellsView) RenderFooter(width int) string {
54		return theme.EmptyLineBg(width) + "\n" + theme.BgLine("FOOTER", width)
55	}
