94	// dimOnBackground is a dim run that keeps the background (Rule 115): unlike
95	// theme.DimStyle, whose reset would leave the cells after it on the terminal's.
96	func dimOnBackground(s string) string {
97		return lipgloss.NewStyle().Background(theme.ColorBackground).Foreground(theme.ColorDim).Render(s)
98	}
