100	// cellsBody is a body of ordinary rows, every styled run on the background
101	// (Rule 115): plain text, a row padded with the
102	// background, coloured runs, wide and emoji glyphs, a Nerd Font icon, blank rows.
103	func cellsBody() string {
104		inner := framesWidth - 2
105		return strings.Join([]string{
106			"",
107			"  plain row, no style at all",
108			theme.PadWithBg("  row padded with the background", inner),
109			theme.Bg("  ") + theme.KeyStyle.Render("key") + theme.Bg(" ") + dimOnBackground("dim text") + theme.Bg(" then plain"),
110			theme.Bg("  ") + theme.StatusErrorStyle.Render("error") + theme.Bg(" on the background"),
111			"  wide: 世界  emoji: ❤️ ✔️  icon: " + theme.IconOK + " ok",
112			"",
113			"  last row",
114		}, "\n")
115	}
