117	// overflowBody has rows wider than the inner width (118 cells here): plain,
118	// styled, and one whose wide glyphs straddle the right edge.
119	func overflowBody() string {
120		return strings.Join([]string{
121			"short row",
122			strings.Repeat("0123456789", 20),
123			theme.KeyStyle.Render(strings.Repeat("k", 150)),
124			strings.Repeat("a", 115) + "世世世" + "tail",
125			"short row again",
126		}, "\n")
127	}
