129	// resetBody has rows that end on a reset (\x1b[m or \x1b[0m): the reset drops the
130	// background the viewport style set, so the padding after it is covered only if
131	// something repaints it.
132	func resetBody() string {
133		return strings.Join([]string{
134			"plain, then \x1b[1mbold to the end of the row\x1b[m",
135			"\x1b[38;2;255;0;0mred to the end\x1b[0m",
136			"\x1b[48;2;1;2;3mown background to the end\x1b[m",
137			"ordinary row",
138		}, "\n")
139	}
