142	// padding: whoever wrote the row left it without a background, and the router
143	// does not repair it.
144	func resetThenTextBody() string {
145		return strings.Join([]string{
146			"plain, then \x1b[1mbold\x1b[m and the rest after a reset",
147			"\x1b[38;2;255;0;0mred\x1b[0m   spaces after a 0m reset",
148			"\x1b[48;2;1;2;3mown background\x1b[m then plain text",
149			"ordinary row",
150		}, "\n")
151	}
