231	func TestFrameHasNoBareCell(t *testing.T) {
232		useDefaultTheme(t)
233		for _, c := range frameCases() {
234			t.Run(c.name, func(t *testing.T) {
235				frame := c.build(t).Render()
236	
237				// A missing cell is as bare as one on the default background.
238				rows := testutil.Cells(frame)
239				if len(rows) != framesHeight {
240					t.Errorf("frame has %d rows, want %d", len(rows), framesHeight)
241				}
242				for r, row := range rows {
243					if len(row) != framesWidth {
244						t.Errorf("row %d has %d cells, want %d", r, len(row), framesWidth)
245						break
246					}
247				}
248	
249				bare := testutil.BareCells(frame)
250				switch {
251				case len(bare) == 0 && c.knownBare != "":
252					t.Errorf("no bare cell any more: remove knownBare (%q) from the case", c.knownBare)
253				case len(bare) > 0 && c.knownBare != "":
254					t.Logf("KNOWN GAP, not asserted: %d bare cells (%s)\n%s", len(bare), c.knownBare, describeBare(bare))
255				case len(bare) > 0:
256					t.Errorf("%d cells on the terminal's default background (Rule 115)\n%s", len(bare), describeBare(bare))
257				}
258			})
259		}
