262	// describeBare summarises bare cells by row: the row, how many, and the columns
263	// of the first and last.
264	func describeBare(bare []testutil.Pos) string {
265		var b strings.Builder
266		shown := 0
267		for i := 0; i < len(bare); {
268			j := i
269			for j < len(bare) && bare[j].Row == bare[i].Row {
270				j++
271			}
272			if shown++; shown > 12 {
273				fmt.Fprintf(&b, "  ... %d more rows\n", countRows(bare[i:]))
274				break
275			}
276			fmt.Fprintf(&b, "  row %d: %d cells, columns %d to %d\n", bare[i].Row, j-i, bare[i].Col, bare[j-1].Col)
277			i = j
278		}
279		return b.String()
280	}
281	
282	func countRows(bare []testutil.Pos) int {
283		n := 0
284		for i, p := range bare {
285			if i == 0 || p.Row != bare[i-1].Row {
286				n++
287			}
288		}
289		return n
290	}
