292	func TestFrameCellsGolden(t *testing.T) {
293		useDefaultTheme(t)
294		for _, c := range frameCases() {
295			t.Run(c.name, func(t *testing.T) {
296				got := testutil.FormatCells(testutil.Cells(c.build(t).Render()))
297				path := filepath.Join(framesDir, c.name+".cells")
298				if *updateFrames {
299					if err := os.MkdirAll(framesDir, 0o755); err != nil {
300						t.Fatal(err)
301					}
302					if err := os.WriteFile(path, []byte(got), 0o644); err != nil {
303						t.Fatal(err)
304					}
305					return
306				}
307				want, err := os.ReadFile(path)
308				if err != nil {
309					t.Fatalf("%v\nrecord it with: go test ./internal/app -run TestFrameCellsGolden -update-frames -count=1", err)
310				}
311				if got != string(want) {
312					t.Errorf("the frame's cells changed (%s); first differences:\n%s\nif intended: go test ./internal/app -run TestFrameCellsGolden -update-frames -count=1",
313						path, firstDifferences(string(want), got, 10))
314				}
315			})
316		}
317	}
