319	// firstDifferences lists up to limit lines where want and got differ.
320	func firstDifferences(want, got string, limit int) string {
321		w, g := strings.Split(want, "\n"), strings.Split(got, "\n")
322		var b strings.Builder
323		n := 0
324		for i := 0; i < max(len(w), len(g)); i++ {
325			var wl, gl string
326			if i < len(w) {
327				wl = w[i]
328			}
329			if i < len(g) {
330				gl = g[i]
331			}
332			if wl == gl {
333				continue
334			}
335			fmt.Fprintf(&b, "  line %d\n    want %q\n    got  %q\n", i+1, wl, gl)
336			if n++; n >= limit {
337				b.WriteString("  ...\n")
338				break
339			}
340		}
341		return b.String()
342	}
