19	// The frame, compared by cells (DEVDESK-281, task 281.2).
20	//
21	// The router assembles the frame in a few passes (renderBody's Style.Width,
22	// fitHeight, the whole-frame lipgloss.Place, the palette overlay). Changing how
23	// one of them pads changes bytes without necessarily changing what a terminal
24	// shows, so the safety net is not a byte comparison: testutil.Cells decodes the
25	// frame into (glyph, foreground, background) per cell, and
26	//
27	//   - TestFrameHasNoBareCell holds Rule 115: no cell of the frame is left on the
28	//     terminal's default background, and the frame is exactly width x height;
29	//   - TestFrameCellsGolden compares the whole decoded frame, case by case,
30	//     against internal/app/testdata/frames/<case>.cells.
31	//
32	// Both run at 120x40 with the TrueColor profile, on the default theme.
33	//
34	// Regenerate the goldens after an intended rendering change, then read the diff
35	// as cells:
36	//
37	//	go test ./internal/app -run TestFrameCellsGolden -update-frames -count=1
38	//
39	// The flag is the package's own: pass it with the package path, not ./...
40	
41	var updateFrames = flag.Bool("update-frames", false, "rewrite internal/app/testdata/frames/*.cells from the current frames")
42	
43	const (
44		framesWidth  = 120
45		framesHeight = 40
46		framesDir    = "testdata/frames"
47	)
48	
49	// cellsView is a footedView whose footer carries its own background: footedView's
50	// writes "FOOTER" with none, and this net would rightly call those cells bare.
51	type cellsView struct{ footedView }
52	
53	func (v *cellsView) RenderFooter(width int) string {
54		return theme.EmptyLineBg(width) + "\n" + theme.BgLine("FOOTER", width)
55	}
56	
57	// Update keeps the wrapper: the promoted one would hand the router the inner view.
58	func (v *cellsView) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
59		_, cmd := v.footedView.Update(msg)
60		return v, cmd
61	}
62	
63	func newCellsView(title, body string) *cellsView {
64		return &cellsView{footedView{fakeView{title: title, body: body}}}
65	}
66	
67	// shortFooterView is a cellsView whose footer is one line shorter than the
68	// GetFooterHeight it declares, so the stacked frame is a row short of the
69	// screen. The router does not fill that row: the whole-frame lipgloss.Place
70	// does, and it is the one thing Place still pads in practice (it never adds
71	// columns once a line, the header's, is as wide as the screen). This is the
72	// case that guards what a different padding pass must keep doing.
73	type shortFooterView struct{ cellsView }
74	
75	func (v *shortFooterView) RenderFooter(width int) string {
76		return theme.BgLine("a footer one line short of its declared height", width)
77	}
