101	// (Rule 115): plain text, a row padded with the
102	// background, coloured runs, wide and emoji glyphs, a Nerd Font icon, blank rows.
103	func cellsBody() string {
104		inner := framesWidth - 2
105		return strings.Join([]string{
106			"",
107			"  plain row, no style at all",
108			theme.PadWithBg("  row padded with the background", inner),
